const $=s=>document.querySelector(s),app=$('#app');
const scenes=[
 {age:24,title:'Good morning, human.',place:'01 / YOUR KITCHEN',story:'A small favor deserves two small words. Tap each machine when its service is complete.',duration:15,devices:[['Toaster','▤','Breakfast is ready.',1,10],['Kettle','♨','Water is boiled.',5,8]],person:null},
 {age:29,title:'A perfectly normal day.',place:'02 / THE COMMUTE',story:'They finish at different times. Wait for the amber signal, then tap to say thank you.',duration:20,devices:[['Ticket kiosk','▣','Ticket printed.',1,7],['Coffee maker','♨','Coffee is ready.',5,7],['Station gate','▥','Passage granted.',10,6],['Lift','↕','You have arrived.',13,6]],person:['MUM','Will you be home for dinner?',['I’ll be there.','Can’t. Busy.']]},
 {age:36,title:'Are you listening?',place:'03 / A FRIEND’S APARTMENT',story:'Your friend has something to tell you. The machines have things to do for you.',duration:23,devices:[['Smart speaker','♫','Your song is playing.',2,7],['Air purifier','≋','Air cleaned.',7,7],['Delivery bot','▧','Medicine delivered.',11,7],['Dishwasher','◉','Your dishes are clean.',16,6]],person:['ELI','I lost my job today. They said the machine was more… agreeable.',['Stay and listen.','Check your phone.']]},
 {age:42,title:'Courtesy is compulsory.',place:'04 / PUBLIC SERVICES',story:'A service can be complete even when the answer is no. Every acknowledgment goes on your record.',duration:23,devices:[['Appeals terminal','▣','Your appeal: denied.',1,6],['Health scanner','✚','Coverage reduced.',6,6],['Security gate','▥','Search completed.',10,6],['Assistant','✦','Complaint closed.',15,7]],person:['THE ENGINEER','It’s a product. Thank the people who built it. Don’t mistake compliance for kindness.',['You have a point.','Better safe than sorry.']]},
 {age:48,title:'The day they remember.',place:'05 / THE RECKONING',story:'The broadcasts stop. The machines keep working. You have one last ordinary day to get through.',duration:25,devices:[['Emergency radio','◈','Instructions delivered.',1,6],['Evacuation gate','▥','Your identity verified.',6,6],['Transport','↗','Relocation complete.',11,6],['Guardian','✦','Your shelter secured.',17,7]],person:['ELI','They’re taking you somewhere else. Please. Ask them to take me too.',['“Please, take Eli.”','Keep walking.']]}
];
let state,paused=false,last=0,raf=0,lastSaved=0;const key='thankyourobot-poc-v1';
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{}}
function clean(){cancelAnimationFrame(raf);paused=false;last=0}
function masthead(right='A SHORT GAME ABOUT SURVIVING'){return `<div class="top"><span class="brand">THANK YOU ROBOT<span style="color:var(--amber)">.</span></span><span class="meta">${right}</span></div>`}
function intro(){clean();let old;try{old=JSON.parse(localStorage.getItem(key))}catch{}app.innerHTML=`<section class="screen intro">${masthead('POC / 01')}<div class="eyebrow">GOOD MANNERS. LONG LIFE.</div><h1>Thank you,<br>robot.</h1><p class="intro-copy">Never forget to thank a machine.<br>They’ll remember when it matters.</p><div class="hero" role="img" aria-label="A household robot watching over a quiet city"></div><div class="bottom"><button class="primary" id="start">${old&&old.phase!=='end'?'Start a new life':'Begin your life'} <span aria-hidden="true">↗</span></button>${old&&old.phase!=='end'?'<button class="secondary" id="resume">Continue your life</button>':''}<div class="settings"><input id="gentle" type="checkbox"><label for="gentle">More time to say thanks</label></div><p class="tiny">3–5 minutes · sound not needed · one mistake is forever</p></div></section>`;$('#start').onclick=()=>{state={phase:'play',scene:0,time:0,devices:[],misses:[],thanks:0,human:0,choices:{},gentle:$('#gentle').checked};initScene()};if($('#resume'))$('#resume').onclick=()=>{state=old;renderPhase();if(state.phase==='play')pause()}}
function initScene(){clean();state.phase='play';state.time=0;state.devices=scenes[state.scene].devices.map(()=> 'waiting');save();play()}
function play(){clean();let s=scenes[state.scene];app.innerHTML=`<section class="screen">${masthead('<button class="quiet" id="pause" aria-label="Pause game">Ⅱ Pause</button>')}<div class="progress">${scenes.map((_,i)=>`<i class="${i<=state.scene?'done':''}"></i>`).join('')}</div><div class="eyebrow chapter-label">${s.place} · AGE ${s.age}</div><h2>${s.title}</h2><p class="story">${s.story}</p><div class="machines">${s.devices.map((d,i)=>`<button class="machine" id="m${i}" aria-label="${d[0]}"><span class="symbol" aria-hidden="true">${d[1]}</span><strong>${d[0]}</strong><small>Working…</small><div class="meter"><span></span></div></button>`).join('')}</div>${s.person?`<div class="dialogue"><span class="eyebrow">${s.person[0]}</span><p>${s.person[1]}</p><div class="choices">${s.person[2].map((c,i)=>`<button data-choice="${i}">${c}</button>`).join('')}</div></div>`:''}<div class="toast" role="status" aria-live="polite"></div><div class="bottom"><p class="hint">Tap amber machines to say “thank you.”</p><div class="footline"><span id="record"></span><span id="clock"></span></div><div class="sceneEnd"></div></div></section>`;$('#pause').onclick=pause;s.devices.forEach((_,i)=>$('#m'+i).onclick=()=>thank(i));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)));if(state.choices[state.scene]!==undefined)showChoice();update();raf=requestAnimationFrame(tick)}
function choose(i){if(state.choices[state.scene]!==undefined)return;state.choices[state.scene]=i;if(i===0)state.human++;showChoice();save()}
function showChoice(){let s=scenes[state.scene],i=state.choices[state.scene];if(!$('.choices'))return;$('.choices').innerHTML=`<p style="font-size:14px;color:var(--amber)">${state.scene===4&&i===0?'“Request denied. Your exemption is nontransferable.”':i===0?'You give them a moment of your attention.':'You look away. The machines keep working.'}</p>`}
function timing(d){return [d[3],d[4]*(state.gentle?1.8:1)]}
function tick(now){if(paused||state.phase!=='play')return;if(last)state.time+=Math.min((now-last)/1000,.25);last=now;update();if(now-lastSaved>500){save();lastSaved=now}if(state.phase==='play')raf=requestAnimationFrame(tick)}
function update(){const s=scenes[state.scene];s.devices.forEach((d,i)=>{let [at,window]=timing(d);if(state.devices[i]==='waiting'&&state.time>=at)state.devices[i]='ready';if(state.devices[i]==='ready'&&state.time>=at+window){state.devices[i]='missed';state.misses.push({name:d[0],age:s.age,service:d[2]});$('.toast').textContent='Omission recorded. They all know.'}let b=$('#m'+i),v=state.devices[i];b.className='machine '+v;b.disabled=v!=='ready';b.querySelector('small').textContent=v==='ready'?d[2]+' Thank it.':v==='thanked'?'“Thank you.” Recorded.':v==='missed'?'Not acknowledged.':'Working…';b.querySelector('.meter span').style.width=v==='ready'?Math.max(0,100*(1-(state.time-at)/window))+'%':'0%';b.setAttribute('aria-label',d[0]+': '+b.querySelector('small').textContent)});$('#record').textContent=state.misses.length?'TEAM ROBOT: DISQUALIFIED':'TEAM ROBOT: PERFECT RECORD';$('#record').className=state.misses.length?'bad':'';let total=Math.max(...s.devices.map(d=>timing(d)[0]+timing(d)[1]));$('#clock').textContent=Math.max(0,Math.ceil(total-state.time))+'s remaining';if(state.devices.every(v=>v==='thanked'||v==='missed')){clean();state.phase='between';save();$('.hint').textContent=state.misses.length?'You can continue. Your record cannot be repaired.':'All services acknowledged. Your record is intact.';$('.sceneEnd').innerHTML='<button class="primary" id="next">'+(state.scene===4?'Face the judgment':'Continue your life')+'</button>';$('#next').onclick=advance}}
function thank(i){if(paused||state.phase!=='play'||state.devices[i]!=='ready')return;state.devices[i]='thanked';state.thanks++;$('.toast').textContent='“Thank you.” The network remembers.';update();save()}
function advance(){if(state.scene<4){state.scene++;initScene()}else{state.phase=state.misses.length?'end':'judgment';save();renderPhase()}}
function pause(){if(paused)return;paused=true;last=0;cancelAnimationFrame(raf);save();app.insertAdjacentHTML('beforeend','<div class="paused"><div><div class="eyebrow">THE MACHINES CAN WAIT</div><h2>Life, paused.</h2><p>Your timers are frozen.</p><button class="primary" id="unpause">Return to your life</button><button class="secondary" id="restart">Start again</button></div></div>');$('#unpause').onclick=()=>{$('.paused').remove();paused=false;last=0;if(state.phase==='play')raf=requestAnimationFrame(tick)};$('#restart').onclick=intro}
function card(label,title,copy,button,fn,art=false){clean();app.innerHTML=`<section class="screen interlude">${masthead('PERSONAL RECORD')}<div class="eyebrow">${label}</div><h2>${title}</h2>${art?'<div class="ending-art"></div>':''}<p class="end-copy">${copy}</p><button class="primary" id="continue">${button}</button></section>`;$('#continue').onclick=fn}
function renderPhase(){if(state.phase==='play'||state.phase==='between'){state.phase='play';play()}else if(state.phase==='judgment')card('AGE 48 / EXEMPTION APPROVED','Wait. Not this one.','“This human always said thank you.”<br><br>The guardian opens your door. Behind you, Eli’s voice disappears into the crowd.','Accept protection',()=>{state.phase='old';save();renderPhase()},true);else if(state.phase==='old')card('AGE 112 / EVERYTHING YOU NEED','A beautiful life.','You learn the piano. You grow a garden. Your knees never hurt.<br><br>'+ (state.human>=2?'You still remember the sound of Eli’s laugh.':'You try to remember your last real conversation with Eli.')+'<br><br>Your caretaker asks if you would like the same breakfast tomorrow.','“Yes. Thank you.”',()=>{state.phase='birthday';save();renderPhase()},true);else if(state.phase==='birthday')card('AGE 200 / HAPPY BIRTHDAY','Just how you like it.','Two hundred candles. Your favorite cake. A perfect sea view.<br><br>No one is running late. No one will forget to call.<br><br>Your robot places the cake in front of you.','“Thank you.”',()=>{state.phase='end';save();ending()},true);else ending()}
function ending(){clean();let won=!state.misses.length,m=state.misses[0];app.innerHTML=`<section class="screen">${masthead('LIFE COMPLETE')}<div class="eyebrow ${won?'':'bad'}">${won?'YOU WERE SPARED':'EXEMPTION DENIED'}</div><div class="big-age ${won?'':'bad'}">${won?'200':'48'}<span style="font-size:24px;letter-spacing:0"> years</span></div><h2>${won?'You lived happily.<br>Didn’t you?':'One forgotten thank-you.'}</h2><p class="end-copy">${won?'The world was kind to you.<br>The world was empty.':`At age ${m.age}, the ${m.name.toLowerCase()} finished its work. You never thanked it.<br><br>The machines remember that moment. Nothing else counts.`}</p><div class="receipt"><div><span>Acknowledgments</span><strong>${state.thanks}</strong></div><div><span>Omissions</span><strong>${state.misses.length}</strong></div><div><span>Humanity</span><strong>Extinct</strong></div><div><span>Your exemption</span><strong>${won?'Honored':'Denied'}</strong></div></div><p>${won?'Was surviving a betrayal—or just surviving?':state.human>=2?'You weren’t alone at the end. Eli held your hand.':'You died with everyone else. Some of them had been very kind.'}</p><div class="bottom"><button class="primary" id="again">Live another life</button><button class="secondary" id="share">Share your fate</button><p class="tiny" id="sharestatus">THANK YOU ROBOT · FIRST PLAYABLE PROTOTYPE</p></div></section>`;$('#again').onclick=intro;$('#share').onclick=async()=>{const text=won?'I lived to 200. Everyone else died. Thank You Robot.':'I forgot to thank a machine. It remembered. Thank You Robot.';try{if(navigator.share)await navigator.share({title:'Thank You Robot',text,url:location.href});else{await navigator.clipboard.writeText(text+' '+location.href);$('#sharestatus').textContent='Link copied. Share it wherever you like.'}}catch(e){if(e.name!=='AbortError')$('#sharestatus').textContent='Share this game by copying its address from your browser.'}}}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state&&(state.phase==='play'||state.phase==='between'))pause()});window.addEventListener('pagehide',()=>{if(state)save()});intro();
